Translate("esMX", "moonglade", {
	title = "Claro de la Luna",
	aliases = { "el claro" },
	sections = {
		{
			title = "Resumen",
			text = [=[Claro de la Luna es un valle oculto en las montañas del norte de {link:kalimdor}Kalimdor{/link}, entre {link:felwood}Frondavil{/link} y {link:winterspring}Cuna del Invierno{/link}. En su corazón yace un lago en calma, rodeado de hierba plateada y árboles antiguos, y en sus orillas se alza la aldea de {link:nighthaven}Amparo de la Noche{/link}. Es la tierra sagrada del {link:cenarion-circle}Círculo Cenarion{/link}, la orden de los druidas, y la sede del guardián {link:keeper-remulos}Remulos{/link}, hijo de {link:cenarius}Cenarius{/link}. Ningún ejército lo domina. {link:night-elves}Elfos de la noche{/link} y {link:tauren}tauren{/link} recorren sus senderos como amigos, y sus celadores no toleran ninguna violencia dentro de sus fronteras.]=],
		},
		{
			title = "Orígenes",
			text = [=[Ninguna crónica registra el año en que los druidas hicieron por primera vez de Claro de la Luna su refugio. Sus nombres cuentan algo de su pasado. {link:the-loch}El lago{/link} lleva el nombre de Elune, la diosa de la luna de los {link:night-elves}elfos de la noche{/link}. Los túmulos del este llevan el nombre de {link:malfurion-stormrage}Malfurion Stormrage{/link}, el primer druida, cuyos seguidores aprendieron a dormir durante largas eras en el {link:emerald-dream}Sueño Esmeralda{/link}. Los druidas dicen que quienes hibernan en Claro de la Luna duermen bajo la vigilancia del guardián. Nunca ha sido una ciudad ni una fortaleza, solo un lugar de enseñanza y de descanso.]=],
		},
		{
			title = "El presente",
			text = [=[El claro está en paz, pero el Círculo que habita en él no lo está. {link:malfurion-stormrage}Malfurion{/link} duerme y no ha regresado. En {link:darnassus}Darnassus{/link}, el archidruida {link:fandral-staghelm}Fandral Staghelm{/link} dirige a los druidas de los elfos de la noche, y él y el guardián {link:keeper-remulos}Remulos{/link} han llegado a desconfiar el uno del otro. Cada uno sospecha que el otro lo engaña, mientras la extraña corrupción de {link:teldrassil}Teldrassil{/link} sigue sin curarse. Claro de la Luna, en cambio, se ha abierto al exterior. Sus druidas han acogido a los {link:tauren}tauren{/link}, y a través de ellos a la {link:horde}Horda{/link}. Sus enviados buscan ayuda en cualquier pueblo dispuesto a darla: contra el veneno en {link:darkshore}Costa Oscura{/link}, contra la Vid Vil de Eldre'Thalas y contra un mal antiguo que despierta en {link:silithus}Silithus{/link}. Hace poco, druidas {link:skyborne}shen'dorei{/link}, de una isla lejana en el cielo, han llegado a {link:nighthaven}Amparo de la Noche{/link}, y un espíritu de su tierra natal ha venido a su encuentro.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Los druidas del {link:cenarion-circle}Círculo Cenarion{/link}.{/b} {link:night-elves}Elfos de la noche{/link} y {link:tauren}tauren{/link} que enseñan, estudian y duermen en el claro, dirigidos por el guardián {link:keeper-remulos}Remulos{/link} y su mayordomo, {link:rabine-saturna}Rabine Saturna{/link}.
• {b}Los celadores de Claro de la Luna.{/b} {link:sentinels}Centinelas{/link} del Círculo que mantienen la paz del claro y guardan su santuario.
• {b}Los grandes espíritus.{/b} Espíritus antiguos de la naturaleza, que enseñan a los jóvenes druidas las formas de su especie.
• {b}Los muertos inquietos.{/b} Dentro del {link:stormrage-barrow-dens}Túmulo de Tempestira{/link}, los espíritus de los Druidas de la Garra caídos vagan llenos de ira.
• {b}Los {link:timbermaw-furbolgs}Fauces de Madera{/link}.{/b} Los {link:furbolgs}fúrbolg{/link} del {link:timbermaw-hold}Bastión Fauces de Madera{/link} guardan los túneles que son el único camino hacia el claro, y no dan la bienvenida a todos los viajeros.]=],
		},
		{
			title = "Historia",
			text = [=[• {b}La era de los Ancestros.{/b} Los druidas aprendieron su arte de {link:cenarius}Cenarius{/link} en la {link:war-of-the-ancients}Guerra de los Ancestros{/link}, y lo conservaron durante diez mil años, la mayor parte de ellos pasados en el sueño.
• {b}La {link:third-war}Tercera Guerra{/link}.{/b} Cuando la {link:burning-legion}Legión Ardiente{/link} regresó, los druidas despertaron para luchar. Cenarius cayó en {link:ashenvale}Vallefresno{/link}, y en la {link:battle-of-mount-hyjal}Batalla del Monte Hyjal{/link} {link:nordrassil}Nordrassil{/link} entregó su poder para destruir a {link:archimonde}Archimonde{/link}.
• {b}El Círculo abierto.{/b} Tras la guerra, el Círculo acogió a druidas {link:tauren}tauren{/link}, el primero de ellos {link:hamuul-runetotem}Hamuul Runetotem{/link}. Claro de la Luna se convirtió en tierra común de ambos pueblos.]=],
		},
		{
			title = "Saber del claro",
			text = [=[• Los druidas hablan de Omen, un gran lobo de la {link:war-of-the-ancients}Guerra de los Ancestros{/link} al que la magia demoníaca volvió contra sus aliados. Abatido en Claro de la Luna, duerme en el {link:lake-elune-ara}Lago Elune'ara{/link} y se agita una vez al año, en el Festival Lunar.
• Al sur del claro, más allá de {link:felwood}Frondavil{/link} y {link:winterspring}Cuna del Invierno{/link}, se alzan las alturas del {link:mount-hyjal}Monte Hyjal{/link}, donde {link:nordrassil}Nordrassil{/link} sigue en pie. Los túmulos de los Druidas de la Garra se hunden también bajo esa montaña, y los más profundos se llaman {link:the-barrow-deeps}The Barrow Deeps{/link}.
• {link:umber}Umber{/link}, el archivero de {link:nighthaven}Amparo de la Noche{/link}, advierte a todo visitante que nunca haga esperar a {link:rabine-saturna}Rabine Saturna{/link}. Quienes lo hacen, dice, pueden acabar bañados en miel.]=],
		},
	},
})

Translate("esMX", "nighthaven", {
	title = "Amparo de la Noche",
	sections = {
		{
			title = "Resumen",
			text = [=[Amparo de la Noche es la única aldea de {link:moonglade}Claro de la Luna{/link}, construida a lo largo de las orillas del {link:lake-elune-ara}Lago Elune'ara{/link}. Sus casas están levantadas al antiguo estilo de los elfos de la noche, y junto a ellas se alzan las tiendas de los druidas {link:tauren}tauren{/link} que se han unido al Círculo. {link:rabine-saturna}Rabine Saturna{/link} lleva los asuntos de la aldea en nombre del guardián {link:keeper-remulos}Remulos{/link}. {link:dendrite-starblaze}Dendrite Starblaze{/link} y {link:loganaar}Loganaar{/link} enseñan a los jóvenes druidas que llegan aquí, y el archivero {link:umber}Umber{/link} deambula entre sus estanterías. Jinetes del Círculo llevan a los druidas a {link:darnassus}Darnassus{/link} y a {link:thunder-bluff}Cima del Trueno{/link}, mientras hipogrifos y jinetes del viento esperan en los límites del claro. Amparo de la Noche es remota y vive apartada. Solo en el Festival Lunar abre sus brazos a todos los pueblos del mundo.]=],
		},
	},
})

Translate("esMX", "shrine-of-remulos", {
	title = "Santuario de Remulos",
	sections = {
		{
			title = "Resumen",
			text = [=[El Santuario de Remulos se alza en el noroeste de {link:moonglade}Claro de la Luna{/link}, entre árboles viejos a orillas del lago. Aquí es donde el propio guardián monta guardia con más frecuencia. El santuario es un homenaje a la obra del {link:cenarion-circle}Círculo Cenarion{/link}, la preservación de la naturaleza y del equilibrio, y la celadora {link:tajarri}Tajarri{/link} lo sirve. Los jóvenes druidas que superan la Prueba del Lago traen una baratija de las aguas y la ofrecen en el santuario como señal de respeto. No muy lejos, al norte, tiene su morada el {link:great-bear-spirit}Gran Espíritu del Oso{/link}.]=],
		},
	},
})

Translate("esMX", "lake-elune-ara", {
	title = "Lago Elune'ara",
	aliases = { "Elune'ara" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Lago Elune'ara llena el corazón de {link:moonglade}Claro de la Luna{/link}. Lleva el nombre de Elune, y sus aguas claras y profundas reflejan la luna sobre el claro. {link:nighthaven}Amparo de la Noche{/link} se alza en sus orillas, y hay puentes que lo cruzan donde la tierra se estrecha. {link:the-loch}El lago{/link} forma parte de la enseñanza del Círculo. Los jóvenes druidas se sumergen en sus profundidades en busca de baratijas del santuario, que se desvanecen pronto una vez sacadas al aire. El lago guarda también un secreto más antiguo. Se dice que el lobo caído Omen duerme en su limo, bendecido por Elune e incapaz de morir.]=],
		},
	},
})

Translate("esMX", "stormrage-barrow-dens", {
	title = "Túmulo de Tempestira",
	aliases = { "Túmulos de Tempestira" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Túmulo de Tempestira se encuentra en el sudeste de {link:moonglade}Claro de la Luna{/link}, tras una gran puerta en la ladera. Lleva el nombre de {link:malfurion-stormrage}Malfurion Stormrage{/link}, y es lugar de reposo de druidas. No todos los que yacen allí descansan en paz. Espíritus enfurecidos de los Druidas de la Garra vagan por sus salas y se lanzan sobre cualquiera que entre. El {link:great-cat-spirit}Gran Espíritu Felino{/link}, que mora cerca, guarda tres reliquias de su favor en el túmulo. Una estatua a la entrada presta un manto de sombra a quienes deben escabullirse entre los espíritus para reclamarlas.]=],
		},
	},
})

Translate("esMX", "keeper-remulos", {
	title = "Guardián Remulos",
	subtitle = "Protector de Claro de la Luna",
	found = "El Santuario de Remulos, al noroeste de Amparo de la Noche",
	hint = [=[Busque al hijo de Cenarius en el santuario que lleva su nombre.]=],
	allegiance = "Círculo Cenarion",
	aliases = { "Remulos" },
	sections = {
		{
			title = "Resumen",
			text = [=[El guardián Remulos es un hijo del semidiós {link:cenarius}Cenarius{/link} y el protector de {link:moonglade}Claro de la Luna{/link}. Como su padre, es un ser de la naturaleza salvaje, tanto bosque como carne. Vela por el claro sagrado y por los druidas que duermen en él, y guía al {link:cenarion-circle}Círculo Cenarion{/link} en su obra: la preservación de la naturaleza y del equilibrio.]=],
		},
		{
			title = "Importancia",
			text = [=[Con {link:malfurion-stormrage}Malfurion Stormrage{/link} perdido en el {link:emerald-dream}Sueño Esmeralda{/link}, los druidas tienen dos centros y dos líderes. En {link:darnassus}Darnassus{/link}, el archidruida {link:fandral-staghelm}Fandral Staghelm{/link} gobierna desde las ramas del nuevo Árbol del Mundo. En {link:moonglade}Claro de la Luna{/link}, Remulos guarda la tierra más antigua. Los dos ya no confían el uno en el otro. Remulos ha decidido abrir el claro a todos los que sirven al mundo vivo, {link:tauren}tauren{/link} y elfos de la noche, {link:horde}Horda{/link} y {link:alliance}Alianza{/link} por igual. Es desde su claro, y no desde la ciudad del archidruida, desde donde el Círculo llama ahora a campeones mortales contra los peligros de {link:kalimdor}Kalimdor{/link}.]=],
		},
		{
			title = "Un hijo de Cenarius",
			text = [=[Los guardianes de la arboleda son los hijos de {link:cenarius}Cenarius{/link}, y Remulos es uno de ellos. Su hermano Zaetar fue el primer hijo. Hace mucho tiempo, Zaetar buscó a la princesa Theradras, un gran poder de la tierra elemental, y ella le dio los primeros centauros. Sus propios hijos se volvieron contra él y lo mataron, y Theradras se llevó sus restos a las cuevas de {red:maraudon}Maraudon{/red}. Remulos creyó a su hermano perdido para siempre por la arrogancia y la ira. Después, en la {link:third-war}Tercera Guerra{/link}, su padre cayó ante los orcos en {link:ashenvale}Vallefresno{/link}. Remulos ha perdido mucho a manos de las razas mortales. No les ha cerrado {link:moonglade}el claro{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Protege {link:moonglade}Claro de la Luna{/link} y a los druidas que hibernan allí.
• Guía al {link:cenarion-circle}Círculo Cenarion{/link} desde el {link:shrine-of-remulos}Santuario de Remulos{/link}.
• Por medio de su mayordomo, {link:rabine-saturna}Rabine Saturna{/link}, pide a los pueblos del mundo que ayuden al Círculo en {link:silithus}Silithus{/link} y en las ruinas de Eldre'Thalas.
• Acoge en el claro a los {link:tauren}tauren{/link}, y a través de ellos a la {link:horde}Horda{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de Remulos antes de la era presente: qué papel tuvo en las guerras del mundo antiguo, o cuándo empezó a guardar {link:moonglade}Claro de la Luna{/link}. Esta entrada recoge solo lo que revelan sus palabras y su puesto.]=],
		},
	},
	chapters = {
		{
			title = "El Círculo dividido",
			hint = "Responda a la llamada del Círculo en Claro de la Luna.",
			text = [=[Cuando el Círculo pidió ayuda en el lejano oeste, la llamada llegó a través de {link:thunder-bluff}Cima del Trueno{/link} y de {link:darnassus}Darnassus{/link}. En Cima del Trueno se escuchó con agrado. En Darnassus, el archidruida se negó a escucharla él mismo. Advirtió que {link:moonglade}Claro de la Luna{/link} solo difundía propaganda, y que solo él había sacado a su pueblo de la oscuridad. Su propio segundo admitió que el archidruida y el guardián sospechaban cada uno que el otro lo engañaba. A quienes acudieron de todos modos al claro se les prometió que estaban entre amigos, y que ningún daño de Darnassus los alcanzaría allí.]=],
		},
		{
			title = "La semilla de Zaetar",
			hint = "Lleve al guardián un regalo del espíritu de su hermano.",
			text = [=[En lo profundo de Maraudon, donde Theradras guardaba sus restos, el espíritu de Zaetar permanecía. No quería abandonar a sus hijos, ni siquiera después de todo lo que habían hecho. En su lugar envió la primera semilla que había brotado de la vida que sus restos habían alimentado, con un mensaje para su hermano: que su espíritu perduraba allí. Cuando la semilla llegó a {link:moonglade}Claro de la Luna{/link}, Remulos comprendió. Su hermano no se había perdido. Se había entregado de nuevo a la naturaleza, como era su deber, y por fin había encontrado la paz. El guardián intuyó que la semilla tendría importancia algún día para el pueblo de aquella tierra desgarrada por la guerra.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:rabine-saturna}Rabine Saturna{/link}, enviado a su mayordomo]=],
		},
		{
			text = [=[{link:rabine-saturna}Rabine Saturna{/link}, enviado desde {link:darnassus}Darnassus{/link}]=],
		},
		{ text = "The New Frontier" },
		{ text = "Seed of Life" },
		{ text = "Trial of the Lake, en su santuario" },
	},
	bonds = {
		{ id = "cenarius", name = "Cenarius", note = "su padre" },
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "el primer druida, que duerme" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "su rival en Darnassus" },
		{ id = "rabine-saturna", name = "Rabine Saturna", note = "su mayordomo" },
		{ id = "tajarri", name = "Tajarri", note = "celadora de su santuario" },
		{ id = "keeper-marandis", name = "Guardián Marandis", note = "busca los restos de su hermano" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "trae a los tauren al Círculo" },
	},
})

Translate("esMX", "rabine-saturna", {
	title = "Rabine Saturna",
	subtitle = "Mayordomo del guardián Remulos",
	found = "Amparo de la Noche, junto al lago",
	hint = [=[Busque al mayordomo del guardián en la aldea de Amparo de la Noche.]=],
	allegiance = "Círculo Cenarion",
	aliases = { "Rabine" },
	sections = {
		{
			title = "Resumen",
			text = [=[Rabine Saturna es el mayordomo del guardián {link:keeper-remulos}Remulos{/link}. Habla en nombre del guardián a quienes llegan a {link:moonglade}Claro de la Luna{/link}, y los saluda en nombre de todos los que habitan en el claro sagrado. Es paciente y cortés, y nunca olvida una deuda. El archivero {link:umber}Umber{/link} lo llama la madre de la guarida de {link:nighthaven}Amparo de la Noche{/link}, y no siempre con cariño.]=],
		},
		{
			title = "Importancia",
			text = [=[Rabine es la mano que {link:moonglade}Claro de la Luna{/link} tiende al mundo. A través de él, el Círculo pide a extranjeros de todos los pueblos que hagan lo que sus druidas no pueden hacer solos. Cree que la preservación de {link:azeroth}Azeroth{/link} es una causa que comparten la {link:horde}Horda{/link} y la {link:alliance}Alianza{/link}, sean cuales sean sus disputas, y diga lo que diga el archidruida de {link:darnassus}Darnassus{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Da la bienvenida al claro a los enviados de {link:thunder-bluff}Cima del Trueno{/link} y de {link:darnassus}Darnassus{/link}, y les promete protección allí.
• Envía agentes al oeste, a {link:silithus}Silithus{/link}, donde en otro tiempo se libró una guerra antigua entre los elfos de la noche y un poder ajeno.
• Envía buscadores a las ruinas de la {link:southwind-village}Aldea del Viento del Sur{/link} en pos de un Relicario de Pureza.
• Trata de encerrar un fragmento de la Vid Vil de Eldre'Thalas.]=],
		},
	},
	chapters = {
		{
			title = "El yermo",
			hint = [=[Lleve la carta del mayordomo a los yermos más allá de Un'Goro.]=],
			text = [=[Al oeste del {link:un-goro-crater}Cráter de Un'Goro{/link} se extiende un desierto que pocos elfos de la noche recuerdan. Hace mucho tiempo su pueblo luchó allí contra un enemigo terrible, y lo selló. Rabine teme que ahora algo trabaje para despertarlo. Envió una carta a {link:layo-starstrike}Layo Starstrike{/link}, el agente del Círculo en {link:valor-s-rest}Sosiego del Valor{/link}, el cementerio de los caídos de los yermos. Lo que Layo encontró allí empezó a darle la razón. Con el tiempo, Layo envió a casa un extraño objeto sellado en quitina, destinado al archivero de {link:nighthaven}Amparo de la Noche{/link}.]=],
		},
		{
			title = "La Vid Vil",
			hint = [=[Lleve al mayordomo un fragmento de la vid corrupta, encerrado.]=],
			text = [=[En las salas orientales de Eldre'Thalas, en {link:feralas}Feralas{/link}, un {link:satyrs}sátiro{/link} llamado Alzzin el Modelador Salvaje se había apoderado del Fruto de la Fertilidad y lo había corrompido hasta convertirlo en la Vid Vil. Ningún recipiente corriente podía contener algo tan vil. Rabine recordó un Relicario de Pureza dejado en la {link:southwind-village}Aldea del Viento del Sur{/link}, en {link:silithus}Silithus{/link}, muchos años atrás. Cuando se recuperó el relicario y se encerró en él el fragmento, nombró al portador héroe del Círculo. La guerra, advirtió, estaba lejos de terminar.]=],
		},
	},
	mentions = {
		{ text = "Rabine Saturna" },
		{ text = "Rabine Saturna" },
		{ text = "Wasteland" },
		{ text = "Uncovering Past Secrets" },
		{ text = "A Reliquary of Purity" },
		{ text = "Shards of the Felvine" },
	},
	bonds = {
		{ id = "keeper-remulos", name = "Guardián Remulos", note = "su señor" },
		{ id = "umber", name = "Umber", note = "el archivero del Círculo" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "le envía a los tauren" },
		{ id = "mathrengyl-bearwalker", name = "Mathrengyl Bearwalker", note = "le envía a los elfos de la noche" },
	},
})

Translate("esMX", "dendrite-starblaze", {
	title = "Dendrite Starblaze",
	subtitle = "Maestro de jóvenes druidas",
	found = "Amparo de la Noche, en el norte de la aldea",
	hint = [=[Busque al druida de Amparo de la Noche que enseña a los jóvenes sus primeras formas.]=],
	allegiance = "Círculo Cenarion",
	aliases = { "Dendrite" },
	sections = {
		{
			title = "Resumen",
			text = [=[Dendrite Starblaze es un druida del {link:cenarion-circle}Círculo Cenarion{/link} que enseña en {link:nighthaven}Amparo de la Noche{/link}. Casi todos los jóvenes druidas de los elfos de la noche y de los {link:tauren}tauren{/link} pasan por sus manos. Recibe a cada uno con una oración en voz baja al padre {link:cenarius}Cenarius{/link} y un pequeño gesto invisible que lo llena de poder. Después los envía a aprender de la propia naturaleza.]=],
		},
		{
			title = "Importancia",
			text = [=[Dendrite mantiene la tradición más antigua de los druidas: que las formas de la naturaleza deben ganarse, no simplemente concederse. Envía a sus alumnos ante los grandes espíritus, al lago y entre las bestias enfermas del mundo, y los juzga por lo que traen de vuelta. Ahora acuden a él también druidas {link:skyborne}shen'dorei{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Envía a los jóvenes druidas ante el {link:great-bear-spirit}Gran Espíritu del Oso{/link} para aprender la naturaleza del oso.
• Impone la Prueba del Lago y la Prueba del León Marino a quienes desean adoptar la forma acuática.
• Envió a jóvenes druidas a {link:darkshore}Costa Oscura{/link} cuando {link:auberdine}Auberdine{/link} pidió ayuda a {link:moonglade}Claro de la Luna{/link} con los ciervos envenenados.
• Envía a sus alumnos ante el {link:great-cat-spirit}Gran Espíritu Felino{/link}, y a los {link:skyborne}shen'dorei{/link} ante un espíritu de su propia tierra natal.]=],
		},
	},
	chapters = {
		{
			title = "La senda de la Garra",
			hint = "Busque al Gran Espíritu del Oso por indicación de Dendrite.",
			text = [=[La primera lección de Dendrite es siempre el oso. Envía a cada alumno ante el {link:great-bear-spirit}Gran Espíritu del Oso{/link}, en el noroeste del claro, y espera. Cuando regresan, busca un cambio en sus ojos: una sabiduría nueva, una fuerza aún sin rumbo.]=],
		},
		{
			title = "Veneno en el agua",
			hint = "Ayude a los ciervos de Costa Oscura en nombre del Círculo.",
			text = [=[{link:auberdine}Auberdine{/link} había pedido ayuda a {link:moonglade}Claro de la Luna{/link}, y Dendrite lo convirtió en una lección. Esto no era un ejercicio, advirtió. El agua del {link:cliffspring-falls}Salto de Fonroca{/link} estaba envenenando a los ciervos de {link:darkshore}Costa Oscura{/link}, y el alumno debía curarlos a mano, como lo haría un profano, antes de aprender a hacerlo con una palabra. Auberdine envió su agradecimiento. Dendrite añadió una advertencia propia: algunos en {link:darnassus}Darnassus{/link} eligen no ver la corrupción que se extiende por la tierra.]=],
		},
		{
			title = "El gran felino",
			hint = "Gánese la bendición del Gran Espíritu Felino.",
			text = [=[En estos días, Dendrite envía también a sus alumnos al sur, ante el {link:great-cat-spirit}Gran Espíritu Felino{/link}, junto al {link:stormrage-barrow-dens}Túmulo de Tempestira{/link}. Para los {link:skyborne}shen'dorei{/link} tiene otro guía: un espíritu felino del viento de su propia isla, que llegó al claro y los pidió por su nombre.]=],
		},
	},
	mentions = {
		{ text = "Moonglade" },
		{ text = "Moonglade" },
		{ text = "Great Bear Spirit" },
		{ text = "A Lesson to Learn" },
		{ text = "Trial of the Sea Lion" },
		{ text = "Lessons Anew" },
		{ text = "Power over Poison" },
		{ text = "The Great Cat Spirit" },
		{ text = "The Great Windborne Cat Spirit" },
	},
	bonds = {
		{ id = "great-bear-spirit", name = "Gran Espíritu del Oso", note = "el primer maestro de sus alumnos" },
		{ id = "great-cat-spirit", name = "Gran Espíritu Felino", note = "pone a prueba a sus alumnos" },
		{ id = "avatar-of-saeyleenan", name = "Avatar de Saeyleenan", note = "enseña a sus alumnos shen'dorei" },
		{ id = "tajarri", name = "Tajarri", note = "juzga la Prueba del Lago" },
		{ id = "alanndarian-nightsong", name = "Alanndarian Nightsong", note = "pidió ayuda a Claro de la Luna" },
		{ id = "mathrengyl-bearwalker", name = "Mathrengyl Bearwalker", note = "le envía alumnos" },
	},
})

Translate("esMX", "umber", {
	title = "Umber",
	subtitle = "Archivero del Círculo Cenarion",
	found = "Entre las estanterías de Amparo de la Noche",
	hint = [=[Busque al archivero que deambula entre las estanterías de Amparo de la Noche.]=],
	allegiance = "Círculo Cenarion",
	sections = {
		{
			title = "Resumen",
			text = [=[Umber es el archivero del {link:cenarion-circle}Círculo Cenarion{/link}. Es brillante, despistado y un poco chiflado, y ha salvado tomos en peor estado de lo que la mayoría de los eruditos se atreverían a abrir. Murmura para sí mientras busca en sus estanterías papeles que ha extraviado. Ha oído los rumores en voz baja sobre horrores en el desierto. No siente ningún aprecio por los insectos de ninguna clase, y se alegra de quedarse con sus libros.]=],
		},
		{
			title = "Importancia",
			text = [=[Umber abrió la primera ventana al pasado de {link:silithus}Silithus{/link}. Un pedazo de quitina enviado desde el desierto resultó contener un diario, escrito en una forma muy antigua de la lengua de los elfos de la noche.]=],
		},
	},
	mentions = {
		{ text = "Umber, Archivist" },
		{ text = "Uncovering Past Secrets" },
		{ text = "Under the Chitin Was..." },
	},
	bonds = {
		{ id = "rabine-saturna", name = "Rabine Saturna", note = "la madre de la guarida, en sus palabras" },
	},
})

Translate("esMX", "loganaar", {
	title = "Loganaar",
	subtitle = "Instructor de druidas de Amparo de la Noche",
	found = "Amparo de la Noche",
	hint = [=[Busque al druida que instruye a los miembros del Círculo en Amparo de la Noche.]=],
	allegiance = "Círculo Cenarion",
	sections = {
		{
			title = "Resumen",
			text = [=[Loganaar enseña las artes del druida en {link:nighthaven}Amparo de la Noche{/link}. A diferencia de los maestros de {link:darnassus}Darnassus{/link} y de {link:thunder-bluff}Cima del Trueno{/link}, no sirve a ninguna ciudad. Instruye a cualquier druida del Círculo que llegue al claro, sea {link:night-elves}elfo de la noche{/link} o {link:tauren}tauren{/link}, y no pregunta nada sobre sus ciudades ni sus disputas. En un Círculo dividido entre {link:moonglade}Claro de la Luna{/link} y Darnassus, sus lecciones pertenecen solo al claro.]=],
		},
		{
			title = "Importancia",
			text = [=[Loganaar suele ser quien se entera cuando alguien lejano pide la ayuda de un druida. Cuando un cazador llamado {link:torwa-pathfinder}Torwa Pathfinder{/link} mandó aviso desde el {link:un-goro-crater}Cráter de Un'Goro{/link} de que solo un druida podía ayudarle, fue Loganaar quien transmitió el mensaje.]=],
		},
	},
	mentions = {
		{ text = "{link:torwa-pathfinder}Torwa Pathfinder{/link}" },
	},
	bonds = {
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "enseña en la misma aldea" },
	},
})

Translate("esMX", "tajarri", {
	title = "Tajarri",
	subtitle = "Celadora del Santuario de Remulos",
	found = "El Santuario de Remulos",
	hint = "Hable con la celadora que guarda el santuario del guardián.",
	allegiance = "Círculo Cenarion · Celadores de Claro de la Luna",
	sections = {
		{
			title = "Resumen",
			text = [=[Tajarri es una de las celadoras de más confianza de {link:moonglade}Claro de la Luna{/link}. Guarda el {link:shrine-of-remulos}Santuario de Remulos{/link}, y lo considera un privilegio. Vigila a los jóvenes druidas que vuelven corriendo del lago con baratijas que se desvanecen en las manos, y los apremia cuando el tiempo se acaba. Otros druidas pueden estar buscando en las mismas aguas, y la baratija no espera. También conoce la segunda prueba, y envía a quienes buscan las mitades del Colgante del León Marino a preguntar a la gente del claro dónde se encuentran.]=],
		},
		{
			title = "Importancia",
			text = [=[Tajarri es la jueza de la Prueba del Lago. A través de ella, cada joven druida aprende que el santuario honra el deber más antiguo del Círculo, la custodia del equilibrio de la naturaleza.]=],
		},
	},
	mentions = {
		{ text = "Trial of the Lake" },
		{ text = "Trial of the Lake" },
		{ text = "Trial of the Sea Lion" },
	},
	bonds = {
		{ id = "keeper-remulos", name = "Guardián Remulos", note = "el señor de su santuario" },
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "le envía a los jóvenes" },
	},
})

Translate("esMX", "great-bear-spirit", {
	title = "Gran Espíritu del Oso",
	subtitle = "Maestro de la Garra",
	found = "El noroeste de Claro de la Luna",
	hint = "Busque al sabio espíritu que mora en el noroeste del claro.",
	allegiance = "Los espíritus de la naturaleza · Círculo Cenarion",
	sections = {
		{
			title = "Resumen",
			text = [=[El Gran Espíritu del Oso mora en el noroeste de {link:moonglade}Claro de la Luna{/link}. Es un ser sabio y noble, y para todos los druidas ha sido el primer tutor en la naturaleza del oso. Los druidas de {link:darnassus}Darnassus{/link} dicen que forma parte del mundo desde que el mundo gira entre las estrellas.]=],
		},
		{
			title = "Importancia",
			text = [=[Todo joven druida de la Garra llega aquí al comienzo de la senda. Del espíritu se llevan sabiduría y fuerza. Sus maestros confían en su poder para dar impulso a su propósito. El encuentro es siempre el mismo, dicen los druidas: algo desconcertante y muy intenso.]=],
		},
	},
	mentions = {
		{ text = "Great Bear Spirit" },
		{ text = "Great Bear Spirit" },
	},
	bonds = {
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "le envía alumnos" },
		{ id = "urs-endris", name = "Urs'endris", note = "el espíritu del oso de Zephras" },
	},
})

Translate("esMX", "great-cat-spirit", {
	title = "Gran Espíritu Felino",
	subtitle = "Maestro de la Sombra Silenciosa",
	found = [=[El sur de Claro de la Luna, al oeste del Túmulo de Tempestira]=],
	hint = [=[Busque al espíritu del felino cerca de los túmulos del sur del claro.]=],
	allegiance = "Los espíritus de la naturaleza · Círculo Cenarion",
	sections = {
		{
			title = "Resumen",
			text = [=[El Gran Espíritu Felino mora en el sur de {link:moonglade}Claro de la Luna{/link}, cerca del {link:stormrage-barrow-dens}Túmulo de Tempestira{/link}. Enseña a los jóvenes druidas la naturaleza del felino: astucia, sigilo y ferocidad cuando ya no queda camino por el que huir. Las palabras por sí solas no lo satisfacen. Quienes acuden a él deben mostrar lo que son, no decirlo.]=],
		},
		{
			title = "Importancia",
			text = [=[Quienes desean adoptar su forma deben recuperar primero tres reliquias de su favor en el túmulo, sorteando a los espíritus enfurecidos de los Druidas de la Garra. Una estatua a la entrada del túmulo les presta sigilo. Solo cuando le han devuelto las tres reliquias concede su bendición, y desea a sus alumnos sombras que los oculten y presas que caigan con facilidad bajo sus garras.]=],
		},
	},
	mentions = {
		{ text = "The Great Cat Spirit" },
		{ text = "Blessings of the Great Cat Spirit" },
	},
	bonds = {
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "le envía alumnos" },
		{ id = "avatar-of-saeyleenan", name = "Avatar de Saeyleenan", note = "un espíritu felino de Zephras" },
	},
})

Translate("esMX", "avatar-of-saeyleenan", {
	title = "Avatar de Saeyleenan",
	subtitle = "El Gran Espíritu Felino del Viento",
	found = "El sur de Claro de la Luna, al sur de los puentes gemelos",
	hint = [=[Busque al espíritu del viento que ha llegado al sur del claro desde una isla lejana.]=],
	allegiance = "Los espíritus de Zephras",
	aliases = { "Saeyleenan" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Avatar de Saeyleenan es un espíritu felino del viento de {link:zephras-isle}Zephras Isle{/link}, la tierra natal de los {link:skyborne}shen'dorei{/link}. Ha aparecido hace poco en {link:moonglade}Claro de la Luna{/link} y ha pedido a los druidas de {link:nighthaven}Amparo de la Noche{/link} que le envíen a los jóvenes druidas de su pueblo. Les enseña la forma felina de Zephras, que difiere un poco de la forma conocida en {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[El Avatar es una señal de que los espíritus de {link:zephras-isle}Zephras{/link} no han olvidado a sus hijos. Les impone la misma prueba que el {link:great-cat-spirit}Gran Espíritu Felino{/link}, en los túmulos al este de su lugar. A quienes la superan les da su bendición y el deseo de que los vientos guíen sus pasos. Poco más tiene que enseñarles aquí, dice, y espera volver a verlos en Zephras.]=],
		},
	},
	mentions = {
		{ text = "The Great Windborne Cat Spirit" },
		{ text = "The Great Windborne Cat Spirit" },
		{ text = "Blessings of the Great Windborne Cat Spirit" },
	},
	bonds = {
		{ id = "great-cat-spirit", name = "Gran Espíritu Felino", note = "su homólogo en el claro" },
		{ id = "urs-endris", name = "Urs'endris", note = "un gran espíritu de la misma isla" },
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "guía a sus alumnos" },
	},
})
